(2249557, 309641, 54755, '<td valign="top">DOF iffy</td>', 'DOF iffy', '2006-03-22 22:31:31.000000', NULL, 1),
(2249575, 309067, 49865, '<td valign="top">this is a great image. not the sharpest focus, but i love the composition which extends from upper right corner directionally towards lower left. some sort of a border may have helped with framing, though.</td>', 'this is a great image. not the sharpest focus, but i love the composition which extends from upper right corner directionally towards lower left. some sort of a border may have helped with framing, though.', '2006-03-22 22:38:08.000000', NULL, 1),
